/** Append accepted diagonals after every previous library; existing sprite indices and axis pictures stay intact. Units: atlas pages. */
export function appendExtraViews(library: LibItem[], pages: string[][]) {
  const first = pages.length; pages.push(...PAGES);
  const have = new Set(library.map(it => it.id)), removed = new Set(REMOVED_IDS);
  for (const it of ITEMS) {
    const base = it.id.slice(5, it.id.lastIndexOf(':'));
    if (have.has(it.id) || !have.has(base) || removed.has(base) || removed.has(it.id)) continue;
    library.push({ ...it, tex: [first + it.tex[0], ...it.tex.slice(1)] as LibItem['tex'] });
    have.add(it.id);
    if (OWNER_SCALE[base] !== undefined) OWNER_SCALE[it.id] = OWNER_SCALE[base]!;
  }
}
